#include <iostream>
#include <typeinfo>

class Widget {};

template<typename T>
void f(const T& param) {
    // typeid treats param as if passed by value, stripping its reference
    // and const qualifiers for the purpose of type identification.
    std::cout << "T's type name:     " << typeid(T).name() << '\n';
    std::cout << "param's type name: " << typeid(param).name() << '\n';
}

int main() {
    Widget w;
    const Widget& rw = w;

    f(rw); // T is deduced as Widget, param's type is const Widget&
           // Yet, typeid reports the same (or similar) name for both,
           // misleadingly hiding the reference on param's type.
    return 0;
}
